<script setup>
import {computed,onMounted,ref} from 'vue'
import {Drawer,Dropdown,Menu,MenuItem,Table,message} from 'ant-design-vue'
import {api,can} from '../api'
import {confirmAction} from '../ui'
import {MoreHorizontal,Plus,Search} from '../icons'

const manager=computed(()=>can('faq.manage'))
const kbs=ref([]),items=ref([]),loading=ref(true),busy=ref(false),error=ref('')
const query=ref(''),kbFilter=ref(null),statusFilter=ref(''),show=ref(false),editing=ref(null)
const testQuery=ref(''),testMode=ref('hybrid'),testResult=ref(null),testing=ref(false)
const evidenceQuery=ref(''),evidenceResults=ref([]),evidenceSearching=ref(false)
const blank=()=>({knowledge_base_id:null,standard_question:'',standard_answer:'',variantsText:'',keywordsText:'',category:'',evidence:[],expected_updated_at:null})
const form=ref(blank())
const statuses={draft:'草稿',published:'已发布',inactive:'已停用'}
const routeNames={high:'标准答案直答',medium:'转入文档 RAG',low:'证据不足拒答',unavailable:'问答对检索不可用'}
const columns=[{title:'标准问题',key:'question',width:360},{title:'知识库',dataIndex:'knowledge_base_name',width:150},{title:'分类',dataIndex:'category',width:120},{title:'版本',key:'version',width:80},{title:'状态',key:'status',width:90},{title:'反馈',key:'metrics',width:105},{title:'操作',key:'actions',width:150}]
const filtered=computed(()=>items.value.filter(item=>(!query.value||(item.standard_question+' '+item.standard_answer+' '+item.category).toLowerCase().includes(query.value.toLowerCase()))&&(!kbFilter.value||item.knowledge_base_id===kbFilter.value)&&(!statusFilter.value||item.status===statusFilter.value)))

async function load(){loading.value=true;error.value='';try{const [bases,faqs]=await Promise.all([api('/api/knowledge-bases'+(manager.value?'?include_inactive=true':'')),api('/api/faqs'+(manager.value?'?include_all=true':''))]);kbs.value=bases;items.value=faqs}catch(e){error.value=e.message}finally{loading.value=false}}
function open(item=null){editing.value=item;form.value=item?{knowledge_base_id:item.knowledge_base_id,standard_question:item.standard_question,standard_answer:item.standard_answer,variantsText:(item.variants||[]).join('\n'),keywordsText:(item.keywords||[]).join('，'),category:item.category||'',evidence:item.evidence_refs||[],expected_updated_at:item.updated_at}:blank();if(!form.value.knowledge_base_id&&kbs.value.length)form.value.knowledge_base_id=kbs.value[0].id;evidenceResults.value=[];evidenceQuery.value='';show.value=true;error.value=''}
function split(value){return [...new Set(value.split(/[\n,，;；]+/).map(item=>item.trim()).filter(Boolean))]}
async function save(){busy.value=true;error.value='';try{const body={knowledge_base_id:form.value.knowledge_base_id,standard_question:form.value.standard_question,standard_answer:form.value.standard_answer,variants:split(form.value.variantsText),keywords:split(form.value.keywordsText),category:form.value.category,evidence_chunk_ids:form.value.evidence.map(item=>item.chunk_id),expected_updated_at:form.value.expected_updated_at};await api(editing.value?`/api/faqs/${editing.value.id}`:'/api/faqs',{method:editing.value?'PATCH':'POST',body:JSON.stringify(body)});show.value=false;message.success('问答对草稿已保存');await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function lifecycle(item,status){const action=status==='published'?'发布':'停用';if(!await confirmAction(`${action}“${item.standard_question}”？${status==='published'?'发布后可参与知识问答直答。':'该版本将不再参与新问答。'}`,{title:`${action}问答对`,okText:`确认${action}`}))return;busy.value=true;try{await api(`/api/faqs/${item.id}/lifecycle`,{method:'POST',body:JSON.stringify({status})});message.success(`已${action}`);await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(item){if(!await confirmAction(`永久删除“${item.standard_question}”及其全部历史版本？相关相似问法和使用反馈也会一并删除，且无法恢复。`,{title:'删除问答对',okText:'确认删除',danger:true}))return;busy.value=true;error.value='';try{const result=await api(`/api/faqs/${item.id}`,{method:'DELETE'});message.success(`已删除问答对及 ${result.deleted_versions} 个版本`);await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function version(item){busy.value=true;try{const created=await api(`/api/faqs/${item.id}/versions`,{method:'POST'});await load();open(created);message.success('已创建可编辑的新版本')}catch(e){error.value=e.message}finally{busy.value=false}}
async function findEvidence(){if(!evidenceQuery.value.trim()||!form.value.knowledge_base_id)return;evidenceSearching.value=true;error.value='';try{const result=await api('/api/search',{method:'POST',body:JSON.stringify({query:evidenceQuery.value,mode:'hybrid',knowledge_base_ids:[form.value.knowledge_base_id],top_k:8,rerank:true})});evidenceResults.value=result.results}catch(e){error.value=e.message}finally{evidenceSearching.value=false}}
function selected(chunkId){return form.value.evidence.some(item=>item.chunk_id===chunkId)}
function toggleEvidence(item){if(selected(item.chunk_id))form.value.evidence=form.value.evidence.filter(value=>value.chunk_id!==item.chunk_id);else form.value.evidence.push({chunk_id:item.chunk_id,document_id:item.document_id,page:item.page,section:item.section,text:item.text||item.snippet,source:item.name,version:item.version,knowledge_base_id:item.knowledge_base_id,knowledge_base_name:item.knowledge_base_name,snippet:item.text||item.snippet})}
async function runTest(){if(!testQuery.value.trim())return;testing.value=true;error.value='';try{testResult.value=await api('/api/faqs/search',{method:'POST',body:JSON.stringify({query:testQuery.value,mode:testMode.value,knowledge_base_ids:kbFilter.value?[kbFilter.value]:[],top_k:5,rerank:true})})}catch(e){error.value=e.message}finally{testing.value=false}}
onMounted(load)
</script>

<template><div class="page-stack">
 <div class="page-intro"><div><h2>问答对知识库</h2><p>维护标准问题与答案。高置信命中直接返回标准答案，其余问题继续进入文档 RAG。</p></div><button v-if="manager" class="primary-button" @click="open()"><Plus :size="16"/>新建问答对</button></div>
 <div v-if="error&&!show" class="error-banner" role="alert">{{error}} <button class="text-button" @click="load">重新加载</button></div>
 <section class="card faq-test"><div class="card-header"><div><h3>检索与路由验证</h3><p>使用与知识问答一致的关键词、向量或混合检索，查看置信度决策。</p></div></div><form class="faq-test-form" @submit.prevent="runTest"><div class="search-field"><Search :size="16"/><input v-model="testQuery" class="input" required placeholder="输入用户可能提出的问题"/></div><select v-model="testMode" class="select"><option value="hybrid">混合检索</option><option value="vector">向量检索</option><option value="keyword">关键词检索</option></select><button class="secondary-button" :disabled="testing">{{testing?'检索中…':'验证路由'}}</button></form>
  <div v-if="testResult" class="route-result"><div><span class="badge blue">{{routeNames[testResult.route]}}</span><strong>{{testResult.results[0]?.standard_question||'没有匹配的标准问答'}}</strong><p v-if="testResult.results[0]">综合置信度 {{testResult.results[0].score}} · 关键词 {{testResult.results[0].keyword_score}} · 向量 {{testResult.results[0].vector_score}}</p></div><span class="muted">{{testResult.elapsed_ms}} ms</span></div>
 </section>
 <section class="card"><div class="filter-bar"><div class="search-field"><Search :size="16"/><input v-model="query" class="input" placeholder="搜索问题、答案或分类"/></div><select v-model="kbFilter" class="select"><option :value="null">全部知识库</option><option v-for="kb in kbs" :key="kb.id" :value="kb.id">{{kb.name}}</option></select><select v-if="manager" v-model="statusFilter" class="select"><option value="">全部状态</option><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option></select><span class="muted">共 {{filtered.length}} 条</span><button class="text-button" @click="load">刷新</button></div>
  <Table :columns="columns" :data-source="filtered" row-key="id" :loading="loading" :scroll="{x:1050}" :pagination="{pageSize:10,hideOnSinglePage:true,showSizeChanger:false}" size="middle"><template #bodyCell="{column,record}"><template v-if="column.key==='question'"><strong class="table-title">{{record.standard_question}}</strong><small class="table-description">{{record.standard_answer}}</small></template><template v-else-if="column.key==='version'">v{{record.version}}</template><template v-else-if="column.key==='status'"><span class="badge" :class="record.status==='published'?'green':record.status==='draft'?'blue':'amber'">{{statuses[record.status]}}</span></template><template v-else-if="column.key==='metrics'"><span v-if="record.metrics">{{record.metrics.uses||0}} 次 · 👍 {{record.metrics.helpful||0}}</span><span v-else>—</span></template><template v-else-if="column.key==='actions'"><div class="table-actions"><button v-if="manager&&record.status!=='published'" class="text-button" @click="open(record)">编辑</button><Dropdown v-if="manager" :trigger="['click']"><button class="icon-button" :aria-label="'管理 '+record.standard_question"><MoreHorizontal :size="18"/></button><template #overlay><Menu><MenuItem v-if="record.status!=='published'" key="publish" @click="lifecycle(record,'published')">发布</MenuItem><MenuItem v-if="record.status==='published'" key="version" @click="version(record)">创建新版本</MenuItem><MenuItem v-if="record.status==='published'" key="inactive" @click="lifecycle(record,'inactive')">停用</MenuItem><MenuItem key="delete" danger @click="remove(record)">删除</MenuItem></Menu></template></Dropdown></div></template></template><template #emptyText><div class="empty">暂无问答对。先新建草稿、关联证据，再发布使用。</div></template></Table>
 </section>
 <Drawer :open="show" :title="editing?`编辑问答对 · v${editing.version}`:'新建问答对'" width="min(760px,100vw)" :mask-closable="!busy" @close="show=false"><form class="drawer-form" @submit.prevent="save"><div v-if="error" class="error-banner">{{error}}</div><label class="field">适用知识库<select v-model="form.knowledge_base_id" class="select" required><option v-for="kb in kbs" :key="kb.id" :value="kb.id">{{kb.name}}</option></select></label><label class="field">标准问题<input v-model="form.standard_question" class="input" required minlength="2" maxlength="1000" placeholder="例如：发动机机油应在什么条件下检查？"/></label><label class="field">相似问法<textarea v-model="form.variantsText" class="textarea compact" placeholder="每行一个，例如：&#10;什么时候看机油尺？&#10;检查机油前要熄火吗？"/></label><label class="field">标准答案<textarea v-model="form.standard_answer" class="textarea answer" required placeholder="填写经人工确认、可直接返回给用户的答案"/></label><div class="form-grid"><label class="field">分类<input v-model="form.category" class="input" placeholder="例如：发动机 / 日常保养"/></label><label class="field">关键词<input v-model="form.keywordsText" class="input" placeholder="机油，机油尺，熄火"/></label></div><section class="evidence-box"><div><strong>来源证据</strong><p class="muted">发布前至少选择一个原文片段，回答引用可继续定位到源文件。</p></div><div class="evidence-search"><input v-model="evidenceQuery" class="input" placeholder="输入证据关键词" @keyup.enter.prevent="findEvidence"/><button type="button" class="secondary-button" :disabled="evidenceSearching" @click="findEvidence">{{evidenceSearching?'检索中…':'检索原文'}}</button></div><div v-if="form.evidence.length" class="selected-evidence"><span v-for="item in form.evidence" :key="item.chunk_id" class="evidence-chip">#{{item.chunk_id}} {{item.source}}<button type="button" @click="toggleEvidence(item)">×</button></span></div><div class="evidence-list"><button v-for="item in evidenceResults" :key="item.chunk_id" type="button" class="evidence-result" :class="{selected:selected(item.chunk_id)}" @click="toggleEvidence(item)"><strong>{{item.name}} · #{{item.chunk_id}}</strong><span>{{item.section||'未标章节'}} · 第 {{item.page||'-'}} 页</span><p>{{item.text}}</p></button></div></section><div class="drawer-actions"><button type="button" class="secondary-button" :disabled="busy" @click="show=false">取消</button><button class="primary-button" :disabled="busy">{{busy?'保存中…':'保存草稿'}}</button></div></form></Drawer>
</div></template>

<style scoped>
.faq-test{padding-bottom:18px}.faq-test-form{display:grid;grid-template-columns:minmax(0,1fr) 150px auto;gap:10px;padding:0 20px}.search-field{position:relative;display:flex;align-items:center;min-width:0}.search-field>.ui-icon{position:absolute;left:10px;color:#99a1ae}.search-field .input{padding-left:34px}.route-result{margin:14px 20px 0;padding:13px 15px;border:1px solid #dbe8fb;background:#f7faff;border-radius:7px;display:flex;justify-content:space-between;gap:16px}.route-result>div{min-width:0}.route-result strong{display:block;margin-top:7px}.route-result p{margin:3px 0 0;color:var(--muted);font-size:12px}.table-description{max-width:430px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.textarea.compact{min-height:80px}.textarea.answer{min-height:140px}.evidence-box{display:grid;gap:12px;padding:14px;border:1px solid var(--line);border-radius:8px;background:#fafcff}.evidence-box p{margin:3px 0 0}.evidence-search{display:flex;gap:8px}.evidence-search .input{flex:1}.selected-evidence{display:flex;gap:6px;flex-wrap:wrap}.evidence-chip{display:inline-flex;align-items:center;gap:6px;background:#edf5ff;color:#315f9e;border-radius:5px;padding:4px 8px;font-size:11px}.evidence-chip button{border:0;background:none;color:inherit;padding:0}.evidence-list{display:grid;gap:8px;max-height:280px;overflow:auto}.evidence-result{text-align:left;border:1px solid var(--line);border-radius:6px;background:white;padding:10px 12px;display:grid;gap:3px;color:inherit}.evidence-result:hover,.evidence-result.selected{border-color:#69b1ff;background:#f3f8ff}.evidence-result span{font-size:11px;color:var(--muted)}.evidence-result p{font-size:12px;line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}@media(max-width:760px){.faq-test-form{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.evidence-search{flex-direction:column}.route-result{flex-direction:column}}
</style>
